    inline constexpr uint32_t XeRor32(uint32_t v, int n) { return (v >> (n & 31)) | (v << ((32 - (n & 31)) & 31)); }
    inline constexpr uint32_t XeRol32(uint32_t v, int n) { return (v << (n & 31)) | (v >> ((32 - (n & 31)) & 31)); }
    inline constexpr uint64_t XeRor64(uint64_t v, int n) { return (v >> (n & 63)) | (v << ((64 - (n & 63)) & 63)); }
    inline constexpr uint64_t XeRol64(uint64_t v, int n) { return (v << (n & 63)) | (v >> ((64 - (n & 63)) & 63)); }

    // Verified Decrypt Name Index
    inline uint32_t XeDecryptCIndex(uint32_t value) {
        uint32_t xored = value ^ 0xD81623EB;
        return ((xored & 0xFFFF0000)) ^ _rotr(xored, 16) ^ 0x46406FA7;
    }

    inline DWORD DecryptCIndex(DWORD value) {
        return XeDecryptCIndex(value);
    }

    constexpr uint64_t XenuineLeaDelta = 0xFA57;
    inline uint64_t XenuineDecryptDirect(uint64_t v, uint64_t funcAddr) {
        const uint64_t k = funcAddr + XenuineLeaDelta;
        v += 0xFFFFFFFFEC1E8575ULL;
        v -= k;
        v = XeRol64(v, 48);
        v += 0xFFFFFFFFB1F3647FULL;
        v -= k;
        v = XeRol64(v, 52);
        if (v > 0x7FFFFFFFFFFF) v &= 0x7FFFFFFFFFFFULL;
        return v;
    }

    // Dynamic Xenuine Emulator for PUBG pointers
    class Decryptor {
    private:
        static inline uint64_t Rol64(uint64_t v, int n) {
            n &= 63;
            if (!n) return v;
            return (v << n) | (v >> (64 - n));
        }

        static inline uint64_t Rol8v(uint64_t v, uint8_t n) {
            uint8_t lo = static_cast<uint8_t>(v);
            n &= 7;
            if (n) lo = static_cast<uint8_t>((lo << n) | (lo >> (8 - n)));
            return (v & ~0xFFULL) | lo;
        }

    public:
        uint64_t decryptFunc = 0;
        std::vector<uint8_t> stubCode;

        bool Update(uintptr_t funcAddr, const uint8_t* codeBuf, size_t size) {
            if (!funcAddr || !codeBuf || size < 32) return false;
            decryptFunc = funcAddr;
            stubCode.assign(codeBuf, codeBuf + size);
            return true;
        }

        uint64_t Decrypt(uint64_t cipher) const {
            if (!cipher) return 0;
            // Plaintext passthrough if dynamic decryptor is inactive or pointer is already direct
            if (stubCode.empty() || !decryptFunc) return cipher;

            uint64_t rax = 0, rcx = cipher;
            size_t i = 0;
            const size_t n = stubCode.size();
            while (i < n) {
                uint8_t b = stubCode[i];
                if (b == 0xC3) break;
                if (b == 0x48 && i + 2 < n) {
                    uint8_t nb = stubCode[i + 1];
                    if (nb == 0x8D && stubCode[i + 2] == 0x05) { // lea rax,[rip+disp32]
                        if (i + 7 > n) break;
                        int32_t disp = 0;
                        std::memcpy(&disp, &stubCode[i + 3], 4);
                        rax = decryptFunc + i + 7 + static_cast<int64_t>(disp);
                        i += 7;
                    } else if (nb == 0x8B && stubCode[i + 2] == 0xCA) { // mov rcx,rdx
                        rcx = cipher;
                        i += 3;
                    } else if (nb == 0x8B && stubCode[i + 2] == 0xC1) { // mov rax,rcx
                        rax = rcx;
                        i += 3;
                    } else if (nb == 0x81 && stubCode[i + 2] == 0xF1) { // xor rcx,imm32
                        if (i + 7 > n) break;
                        int32_t imm = 0;
                        std::memcpy(&imm, &stubCode[i + 3], 4);
                        rcx ^= static_cast<uint64_t>(static_cast<int64_t>(imm));
                        i += 7;
                    } else if (nb == 0x81 && stubCode[i + 2] == 0xC1) { // add rcx,imm32
                        if (i + 7 > n) break;
                        int32_t imm = 0;
                        std::memcpy(&imm, &stubCode[i + 3], 4);
                        rcx += static_cast<uint64_t>(static_cast<int64_t>(imm));
                        i += 7;
                    } else if (nb == 0x29 && stubCode[i + 2] == 0xC1) { // sub rcx,rax
                        rcx -= rax;
                        i += 3;
                    } else if (nb == 0x01 && stubCode[i + 2] == 0xC1) { // add rcx,rax
                        rcx += rax;
                        i += 3;
                    } else if (nb == 0xC1 && stubCode[i + 2] == 0xC1) { // rol rcx,imm8
                        if (i + 4 > n) break;
                        rcx = Rol64(rcx, stubCode[i + 3]);
                        i += 4;
                    } else if (nb == 0xC1 && stubCode[i + 2] == 0xC9) { // ror rcx,imm8
                        if (i + 4 > n) break;
                        rcx = Rol64(rcx, -(stubCode[i + 3] & 63));
                        i += 4;
                    } else {
                        break;
                    }
                } else if (b == 0xC0 && i + 2 < n && stubCode[i + 1] == 0xC1) { // rol cl,imm8
                    if (i + 3 > n) break;
                    rcx = Rol8v(rcx, stubCode[i + 2]);
                    i += 3;
                } else {
                    break;
                }
            }
            if (rcx > 0x7FFFFFFFFFFF) rcx &= 0x7FFFFFFFFFFFULL;
            return rcx;
        }
    };
